use vstd::prelude::*;

verus! {
    /// Compute the element‐wise bitwise AND of two equally‐sized `Vec<u8>`.
    ///
    /// # Safety
    /// Requires that `a` and `b` have the same length.
    /// Ensures the result has that same length, and for every index `i`,
    /// `result[i] == a[i] & b[i]`.
    fn bitwise_and(a: Vec<u8>, b: Vec<u8>) -> (result: Vec<u8>)
        requires
            a.len() == b.len(),
        ensures
            result.len() == a.len(),
            forall |i: usize| i < a.len() ==> result[i] == a[i] & b[i],
    {
        let n = a.len();
        let mut res: Vec<u8> = Vec::new();
        let mut i: usize = 0;
        while i < n
            invariant
                // loop index never exceeds the array length
                i <= n,
                // we've built exactly `i` elements so far
                res.len() == i,
                // and each built element is the bitwise AND of the inputs
                forall |j: usize| j < i ==> res[j] == a[j] & b[j],
            decreases n - i,
        {
            let ai: u8 = a[i];
            let bi: u8 = b[i];
            let val: u8 = ai & bi;
            res.push(val);
            i = i + 1;
        }
        res
    }
}

